WITH f AS (SELECT fight_key, any(gil) AS gil, any(players) AS players, any(gf) AS gf FROM bestiary_fights WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND gil IS NOT NULL AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged') GROUP BY fight_key) SELECT gf, countIf(players = 0) AS kills, minIf(gil, players = 0) AS lo, maxIf(gil, players = 0) AS hi, quantileExactIf(0.5)(gil, players = 0) AS median, countIf(players > 0) AS shared FROM f GROUP BY gf ORDER BY gf IS NULL, gf
